class Solution {

    /**
     * @param Integer $left
     * @param Integer $right
     * @return String
     */
    function abbreviateProduct($left, $right) {
        $twos = 0;
        $fives = 0;
        $suffix = 1;          // keep the last few non-zero digits modulo 1e12
        $MOD = 1000000000000; // 1e12, enough to preserve last 10 digits after trimming zeros
        $logSum = 0.0;

        for ($x = $left; $x <= $right; $x++) {
            $v = $x;
            while ($v % 2 == 0) {
                $twos++;
                $v /= 2;
            }
            while ($v % 5 == 0) {
                $fives++;
                $v /= 5;
            }

            $suffix = ($suffix * $v) % $MOD;
            $logSum += log10($x);
        }

        $zeros = min($twos, $fives);
        $extra2 = $twos - $zeros;
        $extra5 = $fives - $zeros;

        for ($i = 0; $i < $extra2; $i++) {
            $suffix = ($suffix * 2) % $MOD;
        }
        for ($i = 0; $i < $extra5; $i++) {
            $suffix = ($suffix * 5) % $MOD;
        }

        $suffixStr = strval($suffix);
        $suffixStr = rtrim($suffixStr, '0');
        if ($suffixStr === '') $suffixStr = '0';

        $digits = (int)floor($logSum) + 1 - $zeros;

        if ($digits <= 10) {
            // Full non-zero product fits in at most 10 digits.
            $full = $suffixStr;
            return $full . 'e' . strval($zeros);
        }

        // Build leading 10 digits from logarithm.
        $frac = $logSum - floor($logSum);
        $lead = (int)floor(pow(10, $frac + 9)); // 10 digits
        $leadStr = strval($lead);

        // Ensure exactly 10 digits
        if (strlen($leadStr) < 10) {
            $leadStr = str_repeat('0', 10 - strlen($leadStr)) . $leadStr;
        }

        $tail = $suffixStr;
        if (strlen($tail) > 10) {
            $tail = substr($tail, -10);
        }

        return $leadStr . '...' . $tail . 'e' . strval($zeros);
    }
}
