     * @return Integer
     */
    function maxScore($nums) {
        $m = count($nums);
        $full = (1 << $m) - 1;

        $g = array_fill(0, $m, array_fill(0, $m, 0));
        for ($i = 0; $i < $m; $i++) {
            for ($j = $i + 1; $j < $m; $j++) {
                $g[$i][$j] = $this->gcd($nums[$i], $nums[$j]);
            }
        }

        $dp = array_fill(0, 1 << $m, -1);
        $dp[0] = 0;

        for ($mask = 0; $mask <= $full; $mask++) {
            if ($dp[$mask] < 0) continue;
            $used = 0;
            for ($t = $mask; $t > 0; $t &= ($t - 1)) $used++;
            $op = intdiv($used, 2) + 1;

            $first = -1;
            for ($i = 0; $i < $m; $i++) {
                if ((($mask >> $i) & 1) == 0) {
                    $first = $i;
                    break;
                }
            }
            if ($first == -1) continue;

            for ($j = $first + 1; $j < $m; $j++) {
                if ((($mask >> $j) & 1) == 0) {
                    $nmask = $mask | (1 << $first) | (1 << $j);
                    $val = $dp[$mask] + $op * $g[$first][$j];
                    if ($val > $dp[$nmask]) $dp[$nmask] = $val;
                }
            }
        }

        return $dp[$full];
    }

    private function gcd($a, $b) {
        while ($b != 0) {
            $t = $a % $b;
            $a = $b;
            $b = $t;
        }
        return $a;
    }
}
