    /**
     * @param Integer[] $flowers
     * @param Integer $newFlowers
     * @param Integer $target
     * @param Integer $full
     * @param Integer $partial
     * @return Integer
     */
    function maximumBeauty($flowers, $newFlowers, $target, $full, $partial) {
        $n = count($flowers);
        sort($flowers);

        $need = [];
        $cntFull = 0;
        for ($i = 0; $i < $n; $i++) {
            if ($flowers[$i] >= $target) $cntFull++;
            else $need[] = $flowers[$i];
        }

        $m = count($need);
        if ($m == 0) return $n * $full;

        $prefix = array_fill(0, $m + 1, 0);
        for ($i = 0; $i < $m; $i++) $prefix[$i + 1] = $prefix[$i] + $need[$i];

        $ans = 0;
        $j = $m; // number of incomplete gardens kept incomplete
        for ($fullCount = 0; $fullCount <= $n; $fullCount++) {
            if ($fullCount > 0) {
                $idx = $n - $fullCount;
                if ($idx < 0) break;
                if ($flowers[$idx] >= $target) {
                    // already full, nothing to spend
                } else {
                    $newFlowers -= ($target - $flowers[$idx]);
                }
            }

            if ($newFlowers < 0) break;

            while ($j > 0 && $need[$j - 1] >= $target) $j--;
            while ($j > 0) {
                $cost = $prefix[$j];
                if ($cost <= $newFlowers) break;
                $j--;
            }

            $partialValue = 0;
            if ($j > 0) {
                $lo = 0;
                $hi = $target - 1;
                while ($lo < $hi) {
                    $mid = intdiv($lo + $hi + 1, 2);
                    $pos = $this->upperBound($need, $j, $mid);
                    $cost = $mid * $pos - $prefix[$pos];
                    if ($cost <= $newFlowers) $lo = $mid;
                    else $hi = $mid - 1;
                }
                $partialValue = $lo;
            }

            $ans = max($ans, $fullCount * $full + $partialValue * $partial);
        }

        return $ans;
    }

    private function upperBound($arr, $len, $x) {
        $l = 0;
        $r = $len;
        while ($l < $r) {
            $m = intdiv($l + $r, 2);
            if ($arr[$m] <= $x) $l = $m + 1;
            else $r = $m;
        }
        return $l;
    }
}
