    /**
     * @param Integer[][] $graph
     * @param Integer[] $initial
     * @return Integer
     */
    function minMalwareSpread($graph, $initial) {
        $n = count($graph);
        sort($initial);
        $infected = array_fill(0, $n, false);
        foreach ($initial as $x) $infected[$x] = true;

        $visited = array_fill(0, $n, false);
        $bestNode = $initial[0];
        $bestSaved = -1;

        for ($i = 0; $i < $n; $i++) {
            if ($visited[$i]) continue;

            $queue = [$i];
            $visited[$i] = true;
            $component = [];
            $infectedCount = 0;
            $singleInfected = -1;

            for ($q = 0; $q < count($queue); $q++) {
                $u = $queue[$q];
                $component[] = $u;
                if ($infected[$u]) {
                    $infectedCount++;
                    $singleInfected = $u;
                }
                for ($v = 0; $v < $n; $v++) {
                    if ($graph[$u][$v] == 1 && !$visited[$v]) {
                        $visited[$v] = true;
                        $queue[] = $v;
                    }
                }
            }

            if ($infectedCount == 1) {
                $saved = count($component);
                if ($saved > $bestSaved || ($saved == $bestSaved && $singleInfected < $bestNode)) {
                    $bestSaved = $saved;
                    $bestNode = $singleInfected;
                }
            }
        }

        return $bestNode;
    }
}
