     * @param Integer $maxSize
     */
    function __construct($maxSize) {
        $this->maxSize = $maxSize;
        $this->stack = [];
        $this->inc = [];
    }

    /**
     * @param Integer $x
     * @return NULL
     */
    function push($x) {
        if (count($this->stack) < $this->maxSize) {
            $this->stack[] = $x;
            $this->inc[] = 0;
        }
    }

    /**
     * @return Integer
     */
    function pop() {
        $n = count($this->stack);
        if ($n == 0) return -1;

        $i = $n - 1;
        $add = $this->inc[$i];
        if ($i > 0) {
            $this->inc[$i - 1] += $add;
        }

        array_pop($this->inc);
        return array_pop($this->stack) + $add;
