    function licenseKeyFormatting($s, $k) {
        $chars = [];
        $n = strlen($s);

        for ($i = 0; $i < $n; $i++) {
            if ($s[$i] !== '-') {
                $chars[] = strtoupper($s[$i]);
            }
        }

        $len = count($chars);
        if ($len === 0) return "";

        $first = $len % $k;
        if ($first === 0) $first = $k;

        $res = implode('', array_slice($chars, 0, $first));
        for ($i = $first; $i < $len; $i += $k) {
            $res .= '-' . implode('', array_slice($chars, $i, $k));
        }

        return $res;
    }
