    /**
     * @param Integer[][] $points
     * @return Integer
     */
    function maxPoints($points) {
        $n = count($points);
        if ($n <= 2) return $n;

        $ans = 2;

        for ($i = 0; $i < $n; $i++) {
            $map = [];
            $same = 1;
            $localMax = 0;

            for ($j = $i + 1; $j < $n; $j++) {
                $dx = $points[$j][0] - $points[$i][0];
                $dy = $points[$j][1] - $points[$i][1];

                if ($dx == 0 && $dy == 0) {
                    $same++;
                    continue;
                }

                $g = $this->gcd(abs($dx), abs($dy));
                $dx = intdiv($dx, $g);
                $dy = intdiv($dy, $g);

                if ($dx < 0) {
                    $dx = -$dx;
                    $dy = -$dy;
                } elseif ($dx == 0) {
                    $dy = 1;
                } elseif ($dy == 0) {
                    $dx = 1;
                }

                $key = $dx . '#' . $dy;
                if (!isset($map[$key])) $map[$key] = 0;
                $map[$key]++;
                if ($map[$key] > $localMax) $localMax = $map[$key];
            }

            $ans = max($ans, $localMax + $same);
        }

        return $ans;
    }

    private function gcd($a, $b) {
        while ($b != 0) {
            $t = $a % $b;
            $a = $b;
            $b = $t;
        }
        return $a == 0 ? 1 : $a;
    }
}
