    /**
     * @param Integer[][] $fruits
     * @param Integer $startPos
     * @param Integer $k
     * @return Integer
     */
    function maxTotalFruits($fruits, $startPos, $k) {
        $n = count($fruits);
        if ($n == 0 || $k < 0) return 0;

        $pos = [];
        $pre = [0];
        for ($i = 0; $i < $n; $i++) {
            $pos[$i] = $fruits[$i][0];
            $pre[$i + 1] = $pre[$i] + $fruits[$i][1];
        }

        $ans = 0;

        $left = 0;
        for ($right = 0; $right < $n; $right++) {
            while ($left <= $right && $this->minSteps($pos[$left], $pos[$right], $startPos) > $k) {
                $left++;
            }
            if ($left <= $right) {
                $sum = $pre[$right + 1] - $pre[$left];
                if ($sum > $ans) $ans = $sum;
            }
        }

        return $ans;
    }

    private function minSteps($l, $r, $s) {
        if ($r <= $s) {
            return $s - $l;
        }
        if ($l >= $s) {
            return $r - $s;
        }
        $leftFirst = 2 * ($s - $l) + ($r - $s);
        $rightFirst = 2 * ($r - $s) + ($s - $l);
        return min($leftFirst, $rightFirst);
    }
}
