    function minCost($maxTime, $edges, $passingFees) {
        $n = count($passingFees);
        $adj = array_fill(0, $n, []);
        foreach ($edges as $e) {
            $x = $e[0];
            $y = $e[1];
            $t = $e[2];
            $adj[$x][] = [$y, $t];
            $adj[$y][] = [$x, $t];
        }

        $INF = PHP_INT_MAX;
        $dist = array_fill(0, $n, array_fill(0, $maxTime + 1, $INF));
        $dist[0][0] = $passingFees[0];

        $pq = new SplPriorityQueue();
        $pq->setExtractFlags(SplPriorityQueue::EXTR_BOTH);
        $pq->insert([0, 0, $passingFees[0]], -$passingFees[0]); // [time, node, cost]

        while (!$pq->isEmpty()) {
            $cur = $pq->extract();
            $state = $cur['data'];
            $time = $state[0];
            $node = $state[1];
            $cost = $state[2];

            if ($cost !== $dist[$node][$time]) continue;
            if ($node === $n - 1) return $cost;

            foreach ($adj[$node] as $nei) {
