    function minCost($maxTime, $edges, $passingFees) {
        $n = count($passingFees);
        $adj = array_fill(0, $n, []);
        foreach ($edges as $e) {
            $x = $e[0];
            $y = $e[1];
            $t = $e[2];
            $adj[$x][] = [$y, $t];
            $adj[$y][] = [$x, $t];
