        $INF = PHP_INT_MAX;
        $dist = array_fill(0, $n, array_fill(0, $maxTime + 1, $INF));
        $dist[0][0] = $passingFees[0];

        $pq = new SplPriorityQueue();
        $pq->setExtractFlags(SplPriorityQueue::EXTR_BOTH);
        $pq->insert([0, 0, $passingFees[0]], -$passingFees[0]); // [time, node, cost]

        while (!$pq->isEmpty()) {
            $cur = $pq->extract();
            $state = $cur['data'];
            $time = $state[0];
            $node = $state[1];
            $cost = $state[2];

            if ($cost !== $dist[$node][$time]) continue;
            if ($node === $n - 1) return $cost;

