     * @param Integer[] $tasks
     * @param Integer $sessionTime
     * @return Integer
     */
    function minSessions($tasks, $sessionTime) {
        $n = count($tasks);
        $full = 1 << $n;
        $sum = array_fill(0, $full, 0);
        for ($mask = 1; $mask < $full; $mask++) {
            $lsb = $mask & (-$mask);
            $i = 0;
            while ((1 << $i) != $lsb) $i++;
            $sum[$mask] = $sum[$mask ^ $lsb] + $tasks[$i];
