        $dp = array_fill(0, $full, $n + 1);
        $dp[0] = 0;

        for ($mask = 1; $mask < $full; $mask++) {
            $sub = $mask;
            while ($sub > 0) {
                if ($sum[$sub] <= $sessionTime) {
                    $dp[$mask] = min($dp[$mask], $dp[$mask ^ $sub] + 1);
                }
                $sub = ($sub - 1) & $mask;
            }
        }

        return $dp[$full - 1];
    }
}
