        $target = intdiv($sum, $k);

        rsort($nums);
        if ($nums[0] > $target) return false;

        $n = count($nums);
        $full = (1 << $n) - 1;
        $memo = array_fill(0, 1 << $n, -1);

        $dfs = function($mask, $currSum) use (&$dfs, &$memo, $nums, $k, $target, $n, $full) {
