    /**
     * @param String[] $stickers
     * @param String $target
     * @return Integer
     */
    function minStickers($stickers, $target) {
        $n = strlen($target);
        $targetCount = array_fill(0, 26, 0);
        for ($i = 0; $i < $n; $i++) {
            $targetCount[ord($target[$i]) - 97]++;
        }

        $filtered = [];
        foreach ($stickers as $s) {
            $cnt = array_fill(0, 26, 0);
            $len = strlen($s);
            for ($i = 0; $i < $len; $i++) {
                $cnt[ord($s[$i]) - 97]++;
            }
            $filtered[] = $cnt;
        }

        $memo = [];
        $memo[""] = 0;

        $solve = function($rem) use (&$solve, &$memo, $filtered) {
            if (isset($memo[$rem])) return $memo[$rem];

            $need = array_fill(0, 26, 0);
            $len = strlen($rem);
            for ($i = 0; $i < $len; $i++) {
                $need[ord($rem[$i]) - 97]++;
            }

            $firstChar = ord($rem[0]) - 97;
            $ans = PHP_INT_MAX;

            foreach ($filtered as $st) {
                if ($st[$firstChar] == 0) continue;

                $next = '';
                for ($c = 0; $c < 26; $c++) {
                    if ($need[$c] > $st[$c]) {
                        $cnt = $need[$c] - $st[$c];
                        $next .= str_repeat(chr(97 + $c), $cnt);
                    }
                }

                $res = $solve($next);
                if ($res != -1) {
                    $ans = min($ans, $res + 1);
                }
            }

            $memo[$rem] = ($ans == PHP_INT_MAX) ? -1 : $ans;
            return $memo[$rem];
        };

        // Sort target letters to make memoization effective
        $chars = str_split($target);
        sort($chars);
        $sortedTarget = implode('', $chars);

        return $solve($sortedTarget);
    }
}
